<?php
/** Veyra Pro advanced business/trial/economics feature set. */
function veyra_trial_settings(): array {
    if(!table_exists('trial_settings')) return ['enabled'=>0];
    $r=db()->query('SELECT * FROM trial_settings WHERE id=1')->fetch(); return $r?:['enabled'=>0];
}
function veyra_save_trial_settings(array $in): array {
    $plan=max(0,(int)($in['service_plan_id']??0));
    db()->prepare('INSERT INTO trial_settings (id,enabled,service_plan_id,traffic_limit_bytes,duration_minutes,max_per_user,cooldown_days) VALUES (1,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),service_plan_id=VALUES(service_plan_id),traffic_limit_bytes=VALUES(traffic_limit_bytes),duration_minutes=VALUES(duration_minutes),max_per_user=VALUES(max_per_user),cooldown_days=VALUES(cooldown_days)')
      ->execute([!empty($in['enabled'])?1:0,$plan?:null,max(0,(int)($in['traffic_limit_bytes']??1073741824)),max(15,(int)($in['duration_minutes']??120)),max(1,(int)($in['max_per_user']??1)),max(0,(int)($in['cooldown_days']??30))]);
    return veyra_trial_settings();
}
function veyra_trial_eligibility(int $userId): array {
    $s=veyra_trial_settings(); if(empty($s['enabled'])) return ['eligible'=>false,'reason'=>'TRIAL_DISABLED'];
    if(empty($s['service_plan_id'])) return ['eligible'=>false,'reason'=>'TRIAL_PLAN_NOT_SET'];
    $q=db()->prepare('SELECT COUNT(*) c,MAX(requested_at) last_at FROM trial_requests WHERE user_id=?');$q->execute([$userId]);$h=$q->fetch()?:[];
    if((int)($h['c']??0)>=(int)$s['max_per_user']) return ['eligible'=>false,'reason'=>'TRIAL_LIMIT_REACHED'];
    if(!empty($h['last_at'])&&(int)$s['cooldown_days']>0&&strtotime((string)$h['last_at'])>time()-((int)$s['cooldown_days']*86400)) return ['eligible'=>false,'reason'=>'TRIAL_COOLDOWN'];
    return ['eligible'=>true,'settings'=>$s];
}
function veyra_request_trial(int $userId): array {
    $e=veyra_trial_eligibility($userId); if(empty($e['eligible'])) throw new RuntimeException((string)$e['reason']); $s=$e['settings'];
    $q=db()->prepare('SELECT sp.*,sg.name group_name,sv.name service_name FROM service_plans sp JOIN service_groups sg ON sg.id=sp.group_id JOIN services sv ON sv.id=sg.service_id WHERE sp.id=?');$q->execute([(int)$s['service_plan_id']]);$plan=$q->fetch();if(!$plan)throw new RuntimeException('TRIAL_PLAN_NOT_FOUND');
    $maps=function_exists('veyra_route_candidates')?veyra_route_candidates((int)$plan['id']):array_values(array_filter(veyra_plan_provider_maps((int)$plan['id']),fn($m)=>!empty($m['is_active'])&&!empty($m['provider_active'])));if(!$maps)throw new RuntimeException('TRIAL_NO_HEALTHY_PROVIDER');
    $map=$maps[0]; $providerId=(int)$map['provider_id']; $cfg=$map['config']??[]; $token=bin2hex(random_bytes(32)); $expires=date('Y-m-d H:i:s',time()+((int)$s['duration_minutes']*60));
    $pdo=db();$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO user_services (user_id,service_plan_id,service_type,display_name,status,traffic_limit_bytes,started_at,expires_at,subscription_token,metadata_json) VALUES (?,? ,"trial",?,"pending",?,NOW(),?,?,?)')->execute([$userId,(int)$plan['id'],'Trial '.trim(($plan['service_name']??'').' '.($plan['title']??'')),(int)$s['traffic_limit_bytes'],$expires,$token,json_encode(['source'=>'trial','phase'=>10],JSON_UNESCAPED_SLASHES)]);$sid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO trial_requests (user_id,service_plan_id,user_service_id,status,expires_at) VALUES (?,?,?,"provisioning",?)')->execute([$userId,(int)$plan['id'],$sid,$expires]);$tid=(int)$pdo->lastInsertId();$pdo->commit();}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();throw$x;}
    try{$username='vytrial_u'.$userId.'_t'.$tid;$driver=veyra_provider_driver($providerId);$targets=function_exists('veyra_map_inbound_ids')?veyra_map_inbound_ids($map):[(string)$map['remote_target_id']];$r=$driver->createService(['email'=>$username,'external_username'=>$username,'inbound_ids'=>$targets,'inbound_id'=>(string)($targets[0]??$map['remote_target_id']),'remote_target_id'=>(string)($targets[0]??$map['remote_target_id']),'provider_config'=>$cfg,'traffic_limit_bytes'=>(int)$s['traffic_limit_bytes'],'expires_at'=>$expires]);$sub=$r['subscription']['url']??$r['subscription_url']??null;$ext=(string)($r['external_client_id']??$r['id']??$username);db()->prepare('INSERT INTO service_instances (user_service_id,provider_id,external_client_id,external_username,remote_target_id,status,subscription_url,traffic_limit_bytes,expires_at,metadata_json) VALUES (?,?,?,?,?,"active",?,?,?,?)')->execute([$sid,$providerId,$ext,$username,(string)$map['remote_target_id'],$sub,(int)$s['traffic_limit_bytes'],$expires,json_encode(['trial'=>true,'provider_result'=>$r],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);$iid=(int)db()->lastInsertId();if(function_exists('veyra_sync_instance_targets'))veyra_sync_instance_targets($iid,$targets);db()->prepare('UPDATE user_services SET status="active" WHERE id=?')->execute([$sid]);db()->prepare('UPDATE trial_requests SET status="active",provisioned_at=NOW() WHERE id=?')->execute([$tid]);db()->prepare('INSERT INTO service_events (user_service_id,service_instance_id,event_type,title,details_json) VALUES (?,? ,"trial_started","Trial started",?)')->execute([$sid,$iid,json_encode(['trial_request_id'=>$tid],JSON_UNESCAPED_SLASHES)]);return veyra_service_public(veyra_service_record($sid,$userId),true);}catch(Throwable $x){db()->prepare('UPDATE trial_requests SET status="failed",reason=? WHERE id=?')->execute([mb_substr($x->getMessage(),0,255),$tid]);db()->prepare('UPDATE user_services SET status="provisioning_failed" WHERE id=?')->execute([$sid]);throw$x;}
}
function veyra_provider_economics(int $providerId): array {$q=db()->prepare('SELECT * FROM provider_economics WHERE provider_id=?');$q->execute([$providerId]);return$q->fetch()?:['provider_id'=>$providerId,'monthly_cost'=>0,'cost_currency'=>'USD','bandwidth_cost_per_gb'=>0,'maintenance_mode'=>0,'soft_capacity_percent'=>90];}
function veyra_save_provider_economics(array $in): array {$pid=(int)($in['provider_id']??0);if($pid<=0||!veyra_provider($pid))throw new RuntimeException('PROVIDER_NOT_FOUND');db()->prepare('INSERT INTO provider_economics (provider_id,monthly_cost,cost_currency,bandwidth_cost_per_gb,maintenance_mode,maintenance_message,soft_capacity_percent) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE monthly_cost=VALUES(monthly_cost),cost_currency=VALUES(cost_currency),bandwidth_cost_per_gb=VALUES(bandwidth_cost_per_gb),maintenance_mode=VALUES(maintenance_mode),maintenance_message=VALUES(maintenance_message),soft_capacity_percent=VALUES(soft_capacity_percent)')->execute([$pid,max(0,(float)($in['monthly_cost']??0)),substr(strtoupper((string)($in['cost_currency']??'USD')),0,8),max(0,(float)($in['bandwidth_cost_per_gb']??0)),!empty($in['maintenance_mode'])?1:0,trim((string)($in['maintenance_message']??''))?:null,max(1,min(100,(int)($in['soft_capacity_percent']??90)))]);return veyra_provider_economics($pid);}
function veyra_provider_analytics(): array {
    $sql='SELECT p.id,p.name,p.driver,p.status,COALESCE(e.monthly_cost,0) monthly_cost,COALESCE(e.cost_currency,"USD") cost_currency,COALESCE(e.bandwidth_cost_per_gb,0) bandwidth_cost_per_gb,COALESCE(e.maintenance_mode,0) maintenance_mode,e.maintenance_message,COALESCE(e.soft_capacity_percent,90) soft_capacity_percent,COUNT(DISTINCT si.id) active_instances,COUNT(DISTINCT si.user_service_id) active_services,COALESCE(SUM(si.traffic_used_bytes),0) traffic_used_bytes,COALESCE(SUM(si.traffic_limit_bytes),0) traffic_limit_bytes FROM service_providers p LEFT JOIN provider_economics e ON e.provider_id=p.id LEFT JOIN service_instances si ON si.provider_id=p.id AND si.status IN ("active","degraded","suspended") GROUP BY p.id ORDER BY p.id';
    $rows=db()->query($sql)->fetchAll()?:[];
    foreach($rows as &$r){$q=db()->prepare('SELECT COALESCE(SUM(x.final_amount),0) revenue_toman FROM (SELECT DISTINCT o.id,o.final_amount FROM service_instances si JOIN user_services us ON us.id=si.user_service_id JOIN orders o ON o.id=us.order_id WHERE si.provider_id=? AND o.status="delivered") x');$q->execute([(int)$r['id']]);$r['revenue_toman']=(int)$q->fetchColumn();$used=(float)$r['traffic_used_bytes']/1073741824;$r['estimated_bandwidth_cost']=(float)$r['bandwidth_cost_per_gb']*$used;}
    unset($r);return $rows;
}
function veyra_advanced_dashboard(): array {return ['phase'=>10,'phase9_skipped'=>true,'trial'=>veyra_trial_settings(),'provider_analytics'=>table_exists('provider_economics')?veyra_provider_analytics():[],'tickets_open'=>table_exists('support_tickets')?(int)db()->query("SELECT COUNT(*) FROM support_tickets WHERE status NOT IN ('closed','resolved')")->fetchColumn():0,'trials_active'=>table_exists('trial_requests')?(int)db()->query("SELECT COUNT(*) FROM trial_requests WHERE status='active' AND (expires_at IS NULL OR expires_at>NOW())")->fetchColumn():0];}
